// audio.js - Web Audio Engine & Sound FX for Guyem Runner
class SoundManager {
  constructor() {
    this.ctx = null;
    this.muted = false;
    this.bgmPlaying = false;
    this.bgmTimer = null;
    this.stepIndex = 0;
    this.angryMomAudio = null;
    this.initAudioElement();
  }

  initAudioElement() {
    try {
      this.angryMomAudio = new Audio('assets/angry_mom.mp3');
      this.angryMomAudio.preload = 'auto';
      this.gentleMomAudio = new Audio('assets/gentle_mom.mp3');
      this.gentleMomAudio.preload = 'auto';
    } catch(e) {
      console.warn('Audio init:', e);
    }
  }

  ensureContext() {
    if (!this.ctx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AudioContext();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.angryMomAudio) this.angryMomAudio.muted = this.muted;
    if (this.gentleMomAudio) this.gentleMomAudio.muted = this.muted;
    return this.muted;
  }

  // --- Sound Effects ---
  playJump() {
    if (this.muted) return;
    this.ensureContext();
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(260, t);
    osc.frequency.exponentialRampToValueAtTime(740, t + 0.16);

    gain.gain.setValueAtTime(0.35, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.18);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + 0.18);
  }

  playSlide() {
    if (this.muted) return;
    this.ensureContext();
    const t = this.ctx.currentTime;

    const bufferSize = Math.floor(this.ctx.sampleRate * 0.22);
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      output[i] = (Math.random() * 2 - 1) * 0.35;
    }

    const whiteNoise = this.ctx.createBufferSource();
    whiteNoise.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(1400, t);
    filter.frequency.exponentialRampToValueAtTime(400, t + 0.22);
    filter.Q.setValueAtTime(2.0, t);

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.35, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.22);

    whiteNoise.connect(filter);
    filter.connect(gain);
    gain.connect(this.ctx.destination);

    whiteNoise.start(t);
    whiteNoise.stop(t + 0.22);
  }

  playDodge() {
    if (this.muted) return;
    this.ensureContext();
    const t = this.ctx.currentTime;
    const freqs = [659.25, 880, 1046.5]; // E5, A5, C6
    freqs.forEach((freq, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, t + idx * 0.05);

      gain.gain.setValueAtTime(0.18, t + idx * 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, t + idx * 0.05 + 0.14);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(t + idx * 0.05);
      osc.stop(t + idx * 0.05 + 0.14);
    });
  }

  playHurt() {
    if (this.muted) return;
    this.ensureContext();
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(240, t);
    osc.frequency.exponentialRampToValueAtTime(80, t + 0.22);

    gain.gain.setValueAtTime(0.3, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.22);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + 0.22);
  }

  playBeep(high = false) {
    if (this.muted) return;
    this.ensureContext();
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(high ? 880 : 440, t);

    gain.gain.setValueAtTime(0.25, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + (high ? 0.25 : 0.15));

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + (high ? 0.25 : 0.15));
  }

  playScratch() {
    this.ensureContext();
    const t = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(950, t);
    osc.frequency.exponentialRampToValueAtTime(45, t + 0.35);

    gain.gain.setValueAtTime(0.5, t);
    gain.gain.exponentialRampToValueAtTime(0.01, t + 0.35);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + 0.35);
  }

  // --- Upbeat Catchy Background Music (Web Audio Arcade Pop) ---
  startBGM() {
    if (this.bgmPlaying) return;
    this.ensureContext();
    this.bgmPlaying = true;
    this.stepIndex = 0;

    const melody = [
      { f: 523.25, l: 0.12 },
      { f: 0,      l: 0.05 },
      { f: 523.25, l: 0.12 },
      { f: 587.33, l: 0.12 },
      { f: 659.25, l: 0.18 },
      { f: 523.25, l: 0.12 },
      { f: 659.25, l: 0.14 },
      { f: 783.99, l: 0.22 },

      { f: 880.00, l: 0.14 },
      { f: 783.99, l: 0.14 },
      { f: 659.25, l: 0.14 },
      { f: 587.33, l: 0.14 },
      { f: 523.25, l: 0.24 },
      { f: 0,      l: 0.08 },
      { f: 587.33, l: 0.14 },
      { f: 659.25, l: 0.18 },

      { f: 698.46, l: 0.14 },
      { f: 659.25, l: 0.14 },
      { f: 587.33, l: 0.14 },
      { f: 523.25, l: 0.14 },
      { f: 493.88, l: 0.20 },
      { f: 523.25, l: 0.14 },
      { f: 587.33, l: 0.24 },
      { f: 0,      l: 0.08 },

      { f: 783.99, l: 0.14 },
      { f: 880.00, l: 0.14 },
      { f: 987.77, l: 0.18 },
      { f: 1046.5, l: 0.28 },
      { f: 880.00, l: 0.14 },
      { f: 783.99, l: 0.14 },
      { f: 659.25, l: 0.20 },
      { f: 523.25, l: 0.30 },
    ];

    const bass = [
      130.81, 130.81, 196.00, 130.81,
      174.61, 174.61, 220.00, 174.61,
      146.83, 146.83, 220.00, 146.83,
      196.00, 196.00, 246.94, 196.00,
      130.81, 130.81, 196.00, 130.81,
      174.61, 174.61, 220.00, 174.61,
      196.00, 196.00, 246.94, 196.00,
      130.81, 196.00, 261.63, 130.81,
    ];

    const stepInterval = 135;

    const playStep = () => {
      if (!this.bgmPlaying) return;
      if (!this.muted) {
        const t = this.ctx.currentTime;
        const melNote = melody[this.stepIndex % melody.length];
        const bassFreq = bass[Math.floor(this.stepIndex / 2) % bass.length];

        if (melNote && melNote.f > 0) {
          const osc = this.ctx.createOscillator();
          const gain = this.ctx.createGain();
          osc.type = 'square';
          osc.frequency.setValueAtTime(melNote.f, t);

          gain.gain.setValueAtTime(0.08, t);
          gain.gain.exponentialRampToValueAtTime(0.001, t + melNote.l);

          osc.connect(gain);
          gain.connect(this.ctx.destination);
          osc.start(t);
          osc.stop(t + melNote.l);
        }

        if (this.stepIndex % 2 === 0) {
          const bOsc = this.ctx.createOscillator();
          const bGain = this.ctx.createGain();
          bOsc.type = 'triangle';
          bOsc.frequency.setValueAtTime(bassFreq, t);

          bGain.gain.setValueAtTime(0.16, t);
          bGain.gain.exponentialRampToValueAtTime(0.01, t + 0.22);

          bOsc.connect(bGain);
          bGain.connect(this.ctx.destination);
          bOsc.start(t);
          bOsc.stop(t + 0.22);
        }

        const beatInMeasure = this.stepIndex % 8;
        if (beatInMeasure === 0 || beatInMeasure === 4) {
          const kOsc = this.ctx.createOscillator();
          const kGain = this.ctx.createGain();
          kOsc.frequency.setValueAtTime(140, t);
          kOsc.frequency.exponentialRampToValueAtTime(30, t + 0.1);
          kGain.gain.setValueAtTime(0.22, t);
          kGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
          kOsc.connect(kGain);
          kGain.connect(this.ctx.destination);
          kOsc.start(t);
          kOsc.stop(t + 0.1);
        } else if (beatInMeasure === 2 || beatInMeasure === 6) {
          const sOsc = this.ctx.createOscillator();
          const sGain = this.ctx.createGain();
          sOsc.type = 'triangle';
          sOsc.frequency.setValueAtTime(200, t);
          sGain.gain.setValueAtTime(0.12, t);
          sGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
          sOsc.connect(sGain);
          sGain.connect(this.ctx.destination);
          sOsc.start(t);
          sOsc.stop(t + 0.08);
        }
      }

      this.stepIndex++;
      this.bgmTimer = setTimeout(playStep, stepInterval);
    };

    playStep();
  }

  stopBGM() {
    this.bgmPlaying = false;
    if (this.bgmTimer) {
      clearTimeout(this.bgmTimer);
      this.bgmTimer = null;
    }
  }

  // --- Sudden Interruption Climax Event ---
  triggerInterruption(onAudioEndCallback) {
    this.stopBGM();
    this.playScratch();

    const playVoice = () => {
      try {
        const audio = this.angryMomAudio || new Audio('assets/angry_mom.mp3');
        audio.volume = 1.0;
        audio.currentTime = 0;
        if (onAudioEndCallback) {
          audio.onended = onAudioEndCallback;
        }
        const promise = audio.play();
        if (promise !== undefined) {
          promise.catch(err => {
            console.warn('Audio play fallback to base64:', err);
            const fallbackAudio = new Audio('data:audio/mp3;base64,' + FALLBACK_ANGRY_MOM_B64);
            if (onAudioEndCallback) fallbackAudio.onended = onAudioEndCallback;
            fallbackAudio.play().catch(e => {
              console.error('Fallback play failed:', e);
              if (onAudioEndCallback) setTimeout(onAudioEndCallback, 3500);
            });
          });
        }
      } catch (e) {
        console.error('Trigger interruption audio error:', e);
        if (onAudioEndCallback) setTimeout(onAudioEndCallback, 3500);
      }
    };

    setTimeout(playVoice, 150);
  }

  // Gentle reminder voice & chime for Slide 14
  playGentleReminder(onAudioEndCallback) {
    this.ensureContext();
    try {
      const t = this.ctx.currentTime;
      const chime1 = this.ctx.createOscillator();
      const gain1 = this.ctx.createGain();
      chime1.type = 'sine';
      chime1.frequency.setValueAtTime(587.33, t);
      gain1.gain.setValueAtTime(0.2, t);
      gain1.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
      chime1.connect(gain1);
      gain1.connect(this.ctx.destination);
      chime1.start(t);
      chime1.stop(t + 0.4);

      const chime2 = this.ctx.createOscillator();
      const gain2 = this.ctx.createGain();
      chime2.type = 'sine';
      chime2.frequency.setValueAtTime(880.0, t + 0.18);
      gain2.gain.setValueAtTime(0.2, t + 0.18);
      gain2.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
      chime2.connect(gain2);
      gain2.connect(this.ctx.destination);
      chime2.start(t + 0.18);
      chime2.stop(t + 0.6);
    } catch(e) {}

    const playVoice = () => {
      try {
        const audio = this.gentleMomAudio || new Audio('assets/gentle_mom.mp3');
        audio.volume = 1.0;
        audio.currentTime = 0;
        if (onAudioEndCallback) audio.onended = onAudioEndCallback;
        const promise = audio.play();
        if (promise !== undefined) {
          promise.catch(err => {
            console.warn('Gentle audio fallback to base64:', err);
            const fallbackAudio = new Audio('data:audio/mp3;base64,' + FALLBACK_GENTLE_MOM_B64);
            if (onAudioEndCallback) fallbackAudio.onended = onAudioEndCallback;
            fallbackAudio.play().catch(e => {
              console.error('Fallback gentle audio failed:', e);
              if (onAudioEndCallback) setTimeout(onAudioEndCallback, 3500);
            });
          });
        }
      } catch (e) {
        console.error('Gentle reminder voice error:', e);
        if (onAudioEndCallback) setTimeout(onAudioEndCallback, 3500);
      }
    };
    setTimeout(playVoice, 150);
  }

  // Victory fanfare for Slide 14 Family Hug
  playVictoryFanfare() {
    if (this.muted) return;
    this.ensureContext();
    const notes = [
      { f: 523.25, t: 0.0, d: 0.22 },
      { f: 659.25, t: 0.14, d: 0.22 },
      { f: 783.99, t: 0.28, d: 0.30 },
      { f: 1046.50, t: 0.45, d: 0.80 }
    ];
    notes.forEach(note => {
      try {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(note.f, this.ctx.currentTime + note.t);
        gain.gain.setValueAtTime(0.28, this.ctx.currentTime + note.t);
        gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + note.t + note.d);
        osc.connect(gain);
        gain.connect(this.ctx.destination);
        osc.start(this.ctx.currentTime + note.t);
        osc.stop(this.ctx.currentTime + note.t + note.d);
      } catch(e) {}
    });
  }
}

const FALLBACK_ANGRY_MOM_B64 = "";

const FALLBACK_GENTLE_MOM_B64 = "";

window.soundManager = new SoundManager();
